const headings = document.querySelectorAll("h1");
if (headings.length !== 1) throw new Error("Expected exactly one h1");
if (headings[0].textContent.trim().length < 2) throw new Error("The h1 should contain a person's name");
return true;

const section = document.querySelector("section#projects");
if (!section) throw new Error("Missing #projects section");
const projects = section.querySelectorAll("article.project");
if (projects.length < 2) throw new Error("Expected at least two project articles");
return true;

const projects = document.querySelectorAll("article.project");
for (const project of projects) {
  const summary = project.querySelector("p.summary");
  if (!summary) throw new Error("Project is missing a summary");
  if (summary.textContent.trim().length < 40) throw new Error("Project summary is too short");
}
return true;

const projects = document.querySelectorAll("article.project");
for (const project of projects) {
  if (!project.querySelector("h3")) throw new Error("Project is missing h3");
  const image = project.querySelector("img");
  if (!image) throw new Error("Project is missing image");
  if (!image.getAttribute("alt") || !image.getAttribute("alt").trim()) throw new Error("Image alt text is empty");
}
return true;

const projects = document.querySelectorAll("article.project");
for (const project of projects) {
  const list = project.querySelector("ul.tech");
  if (!list) throw new Error("Missing technology list");
  if (list.querySelectorAll("li").length < 3) throw new Error("Expected at least three technologies");
}
return true;

const projects = document.querySelectorAll("article.project");
for (const project of projects) {
  const links = [...project.querySelectorAll("a")];
  const live = links.find((link) => link.textContent.trim() === "Live demo");
  const source = links.find((link) => link.textContent.trim() === "Source code");
  if (!live) throw new Error("Missing Live demo link");
  if (!source) throw new Error("Missing Source code link");
  if (!source.getAttribute("href")?.startsWith("https://github.com/")) throw new Error("Source code link must point to GitHub");
}
return true;

const links = document.querySelectorAll('a[target="_blank"]');
for (const link of links) {
  const rel = (link.getAttribute("rel") || "").split(/\s+/).filter(Boolean);
  if (!rel.includes("noopener")) throw new Error("target=_blank link is missing noopener");
}
return true;

const html = document.documentElement;
if (!html.getAttribute("lang") || !html.getAttribute("lang").trim()) throw new Error("Missing html lang attribute");
const description = document.querySelector('meta[name="description"]');
if (!description) throw new Error("Missing meta description");
if (!description.getAttribute("content") || !description.getAttribute("content").trim()) throw new Error("Meta description is empty");
return true;

const section = document.querySelector("section#projects");
const projects = section?.querySelectorAll("article.project") || [];
if (projects.length < 2) throw new Error("Expected project articles");
for (const project of projects) {
  if (!section.contains(project)) throw new Error("Project is outside #projects");
  if (!project.querySelector("h3, p.summary, img, ul.tech, a")) throw new Error("Project content is incomplete");
}
return true;
